using Il2CppInterop.Runtime.InteropTypes.Arrays;
using LeAccess.Accessibility.MapSections;
using UnityEngine;
using UnityEngine.SceneManagement;

int checks=0;
void Check(bool ok,string text){checks++;if(!ok)throw new Exception(text);}
FootstepMaterial Material(int a,int b,int c,int d)=>new(){soundEvent=new(){Guid=new(){Data1=a,Data2=b,Data3=c,Data4=d}}};
var wood=Material(-1599689582,1211331962,1259039645,693955642);
var grass=Material(1422184698,1315540948,1827935151,1868116228);
var unknown=Material(1,2,3,4);
var scene=new Scene{handle=20,name="Map",path="map.unity",Valid=true,isLoaded=true};SceneManager.Scene=scene;
var player=new GameObject{scene=scene};PlayerFinder.player=player;
var body=new GameObject{scene=scene,Parent=player};
var emitter=body.Add(new FootstepSoundEmitter{activeMaterials=new(wood,null),activeVolumes=new(1f,0f)});
var visuals=body.Add(new ActorVisuals());PlayerFinder.playerActorVisuals=visuals;
var ground=new GameObject{scene=scene};
var collider=ground.Add(new Collider());var holder=ground.Add(new ColliderFootstepSoundHolder{A=wood});
var foot=new GameObject{scene=scene,Parent=body};foot.transform.position=new(5,2,8);
var trigger=body.Add(new FootstepRaycastTrigger{emitter=emitter,actorVisuals=visuals,lastCollider=collider,lastHolder=holder,feet=new(foot.transform)});
player.Triggers=new(trigger);
Physics.Hits=new(new RaycastHit{collider=collider,distance=0.6f});
var world=new MapSectionWorldSnapshot(10,20,"Map","map.unity",5,2,8,0.5,null);
bool Read(out string key)=>MapSurfaceProbe.TryRead(world,out key);
Check(Read(out var key)&&key=="map.surface.wood","verified wood plus fresh physical contact");
Check(Physics.Origin.y==2.5f&&Physics.Origin.x==5&&Physics.Direction.y==-1&&Physics.Distance==3&&Physics.Mask==128&&Physics.Query==QueryTriggerInteraction.Ignore,"exact native origin/mask/range/query");
Check(holder.Reads==1,"local getter sampled once");
emitter.ignoreSurfaceSound=true;Check(!Read(out _),"ignoreSurfaceSound silence");emitter.ignoreSurfaceSound=false;
emitter.activeVolumes[0]=0;Check(!Read(out _),"zero volume ignored");emitter.activeVolumes[0]=-1;Check(!Read(out _),"negative volume ignored");
emitter.activeVolumes[0]=float.NaN;Check(!Read(out _),"NaN volume ignored");emitter.activeVolumes[0]=float.PositiveInfinity;Check(!Read(out _),"infinite volume ignored");emitter.activeVolumes[0]=1;
emitter.activeMaterials[0]=unknown;Check(!Read(out _),"unknown GUID is not an artist-name category");emitter.activeMaterials[0]=wood;
wood.WasCollected=true;Check(!Read(out _),"collected material rejected");wood.WasCollected=false;
wood.soundEvent.WasCollected=true;Check(!Read(out _),"collected boxed event rejected");wood.soundEvent.WasCollected=false;
wood.soundEvent.IsNull=true;Check(!Read(out _),"null native GUID rejected");wood.soundEvent.IsNull=false;
emitter.activeMaterials[1]=grass;emitter.activeVolumes[1]=1;Check(!Read(out _),"equal competing surface weights ambiguous");
emitter.activeVolumes[0]=2;holder.WeightA=2;Check(Read(out key)&&key=="map.surface.wood","positive dominant surface selected");
emitter.activeMaterials[1]=unknown;emitter.activeVolumes[1]=3;Check(!Read(out _),"dominant unknown never falls back to smaller known surface");
emitter.activeMaterials[1]=null;emitter.activeVolumes[1]=0;emitter.activeVolumes[0]=1;holder.WeightA=1;
holder.A=grass;Check(!Read(out _),"same-collider changed floor sample excludes stale emitter");holder.A=wood;
Physics.Hits=new();Check(!Read(out _),"teleport away from cached collider rejected");
var otherGround=new GameObject{scene=scene};var otherCollider=otherGround.Add(new Collider());otherGround.Add(new ColliderFootstepSoundHolder{A=wood});
Physics.Hits=new(new RaycastHit{collider=collider,distance=0.6f},new RaycastHit{collider=otherCollider,distance=0.2f});Check(!Read(out _),"nearer different floor blocks stale floor");
Physics.Hits=new(new RaycastHit{collider=collider,distance=0.6f},new RaycastHit{collider=otherCollider,distance=0.6f});Check(!Read(out _),"equal-distance different contacts ambiguous");
Physics.Hits=new(new RaycastHit{collider=collider,distance=0.6f});
collider.isTrigger=true;Check(!Read(out _),"trigger contacts ignored");collider.isTrigger=false;
collider.enabled=false;Check(!Read(out _),"disabled cached collider rejected");collider.enabled=true;
holder.Enabled=false;Check(!Read(out _),"inactive holder rejected");holder.Enabled=true;
foot.Parent=null;Check(!Read(out _),"foreign foot transform rejected");foot.Parent=body;
body.Parent=null;Check(!Read(out _),"reparented cached trigger rejected");body.Parent=player;
emitter.Enabled=false;Check(!Read(out _),"inactive emitter rejected");emitter.Enabled=true;
visuals.dead=true;Check(!Read(out _),"dead owning visuals rejected");visuals.dead=false;
PlayerFinder.playerActorVisuals=body.Add(new ActorVisuals());Check(!Read(out _),"foreign visuals pointer rejected");PlayerFinder.playerActorVisuals=visuals;
trigger.raycastDistance=float.NaN;Check(!Read(out _),"invalid native range rejected");trigger.raycastDistance=3;
FootstepRaycastTrigger.raycastMask=0;Check(!Read(out _),"empty native mask rejected");FootstepRaycastTrigger.raycastMask=128;
holder.B=grass;holder.WeightB=3;emitter.activeMaterials[1]=grass;emitter.activeVolumes[1]=3;Check(Read(out key)&&key=="map.surface.grass","fresh two-surface holder selection");
holder.OnlyWriteFirst=true;emitter.activeMaterials[1]=null;emitter.activeVolumes[1]=0;Check(Read(out key)&&key=="map.surface.wood","local sample buffers cleared before partial getter");holder.OnlyWriteFirst=false;holder.B=null;holder.WeightB=0;
emitter.useOverrideMaterials=true;emitter.overrideMaterialA=unknown;emitter.overrideVolumeA=1;
Check(!Read(out _),"unknown active override cannot inherit old default buffers");
emitter.overrideMaterialA=grass;Check(!Read(out _),"mismatching active override cannot claim cached default surface");
emitter.overrideMaterialA=wood;Check(Read(out key)&&key=="map.surface.wood","verified active override agrees with fresh floor");
emitter.overrideMaterialB=grass;emitter.overrideVolumeB=1;Check(!Read(out _),"equal conflicting overrides ambiguous");
holder.ignoreOverrides=true;Check(Read(out key)&&key=="map.surface.wood","native holder ignoreOverrides uses actual surface buffer");
holder.ignoreOverrides=false;emitter.useOverrideMaterials=false;
var terrain=new TerrainFootstepSoundHolder{A=wood};ground.Add(terrain);ground.Components.Remove(holder);trigger.lastHolder=terrain;
Check(Read(out key)&&key=="map.surface.wood","known terrain pure sampler supported");terrain.A=grass;Check(!Read(out _),"teleport within terrain collider detects fresh blend mismatch");
ground.Components.Remove(terrain);ground.Components.Add(holder);trigger.lastHolder=holder;
var extra=body.Add(new FootstepRaycastTrigger{emitter=emitter,actorVisuals=visuals});player.Triggers=new(trigger,extra);MapSurfaceProbe.Reset();Check(!Read(out _),"multiple owned triggers ambiguous");player.Triggers=new(trigger);Check(Read(out _),"local discovery retries after ambiguity");
scene.isLoaded=false;SceneManager.Scene=scene;Check(!Read(out _),"unloaded scene rejected");scene.isLoaded=true;SceneManager.Scene=scene;
world=world with{ScenePath="foreign"};Check(!Read(out _),"stale snapshot scene path rejected");world=world with{ScenePath="map.unity"};
Physics.Throw=true;Check(!Read(out _)&&!Read(out _)&&LeAccess.Plugin.Log.Warnings.Count==1,"native error diagnostics deduplicate");
MapSurfaceProbe.Reset();Check(!Read(out _)&&LeAccess.Plugin.Log.Warnings.Count==2,"reset clears diagnostics");Physics.Throw=false;
Check(Read(out _),"reset and native recovery restore capture");
using var evidenceStream=typeof(FootstepMaterial).Assembly.GetManifestResourceStream("SurfaceAssetEvidence.json");
using var evidence=System.Text.Json.JsonDocument.Parse(evidenceStream);
foreach(var entry in evidence.RootElement.EnumerateArray())
{
    string name=entry.GetProperty("Name").GetString();var guid=entry.GetProperty("Guid");
    var material=Material(guid.GetProperty("Data1").GetInt32(),guid.GetProperty("Data2").GetInt32(),guid.GetProperty("Data3").GetInt32(),guid.GetProperty("Data4").GetInt32());
    emitter.activeMaterials[0]=holder.A=material;
    bool captured=Read(out key);
    if(name is "Werebear" or "Spriggan" or "Armour") Check(!captured,"authored equipment/form GUID excluded: "+name);
    else Check(captured&&key=="map.surface."+(name.StartsWith("Water_")?"water":name.ToLowerInvariant()),"actual extracted surface GUID: "+name);
}
collider.Destroyed=true;Check(!Read(out _),"destroyed physical contact rejected");
Console.WriteLine($"{checks} map surface checks passed.");
